// WF-04: Validation & Normalization
// Validates required fields, email format, name length, consent.
// Produces reason codes V-001 to V-010 and normalized lead output.

const input = $input.first().json;

// --- Trim fields ---
const fullName = (input.full_name || '').trim();
const email = (input.email || '').trim().toLowerCase();
const projectDesc = (input.project_description || '').trim();
const consent = input.consent_to_contact;

// --- Validation checks ---
const reasonCodes = [];
let isTerminal = false;

// V-001: Missing required field
const missingRequired = !fullName || !email || !projectDesc || consent === undefined || consent === null;
if (missingRequired) {
  reasonCodes.push('V-001');
  isTerminal = true;
}

// V-002: Invalid email format
if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
  reasonCodes.push('V-002');
}

// V-003: Empty project description
if (!projectDesc) {
  reasonCodes.push('V-003');
  isTerminal = true;
}

// V-004: Name too short
if (fullName && fullName.length < 2) {
  reasonCodes.push('V-004');
}

// --- Determine validity ---
const isValid = reasonCodes.length === 0;
if (isValid) {
  reasonCodes.push('V-010');
}

// --- Determine recoverability ---
let recoverability;
if (isValid) {
  recoverability = 'VALID';
} else if (isTerminal) {
  recoverability = 'TERMINAL';
} else {
  recoverability = 'REVIEWABLE';
}

// --- Build normalized lead ---
const normalizedLead = {
  full_name: fullName,
  email: email,
  project_description: projectDesc,
  consent_to_contact: consent === true,
  company_name: (input.company_name || '').trim(),
  company_website: (input.company_website || '').trim(),
  job_title: (input.job_title || '').trim(),
  phone: (input.phone || '').trim(),
  country: (input.country || '').trim(),
  budget_range: (input.budget_range || '').trim(),
  desired_timeline: (input.desired_timeline || '').trim(),
  service_interest: (input.service_interest || '').trim(),
  lead_source: (input.lead_source || '').trim(),
  utm_source: (input.utm_source || '').trim(),
  utm_medium: (input.utm_medium || '').trim(),
  utm_campaign: (input.utm_campaign || '').trim(),
  utm_term: (input.utm_term || '').trim(),
  utm_content: (input.utm_content || '').trim()
};

return [{
  json: {
    lead_id: input.lead_id,
    correlation_id: input.correlation_id,
    is_valid: isValid,
    reason_codes: reasonCodes,
    recoverability: recoverability,
    normalized_lead: normalizedLead,
    source_system: input.source_system || '',
    source_submission_id: input.source_submission_id || '',
    payload_fingerprint: input.payload_fingerprint || '',
    policy_version: input.policy_version || 1
  }
}];
